/** Make sure the generated catalog exists before the suite runs (#52).
 *
 * THE PROBLEM THIS SOLVES. `catalog/` is generated by
 * `sync-catalog.mjs` and gitignored, so `pnpm install` is not enough:
 * a fresh clone — or a fresh git worktree — starts with 147 failing
 * tests, every one of them a variation of "The 2026-2027 course index
 * could not be read".
 *
 * The loader's own error already says to run the sync script. That did
 * not help: the advice arrives 147 times inside a wall of red, and a
 * wall of red reads as "this project is broken", not as "you are one
 * command away". Four agents working in parallel worktrees each hit
 * this, each spent time on it, and each worked out the same fix
 * independently. That is the cost of a setup step that only exists in
 * someone's head.
 *
 * WHY GENERATE RATHER THAN JUST EXPLAIN. The point is that a new
 * contributor reaches a green suite from the README alone. Printing a
 * better message still leaves them to run something they did not know
 * about; this does it, once, and says so.
 *
 * WHY NOT ON EVERY RUN. Regenerating 38 MB on every `vitest` would
 * make the fast suite slow and hide a real dependency behind a delay
 * nobody could explain. The check is "is it absent", not "is it
 * stale": a developer who changes the pipeline still runs the sync
 * themselves, deliberately, which is the one case where being explicit
 * is worth it.
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { execFileSync } from "node:child_process";

const here = path.dirname(fileURLToPath(import.meta.url));
const catalog = path.resolve(here, "..", "catalog");
const editions = path.join(catalog, "editions.json");

if (fs.existsSync(editions)) process.exit(0);

console.log(
  "[mcp] The catalog is generated and not checked in, and it is not here yet.\n" +
    "[mcp] Building it once — about forty seconds. Later runs skip this.",
);

try {
  execFileSync(process.execPath, [path.join(here, "sync-catalog.mjs")], { stdio: "inherit" });
} catch {
  // SAY WHAT TO DO, rather than failing the way the absent catalog
  // already would. If the pipeline data itself is missing there is
  // nothing this script can do about it, and the next 147 errors would
  // bury the only sentence that matters.
  console.error(
    "\n[mcp] Could not build the catalog.\n" +
      "[mcp] The tests need it, and they will fail with 'course index could not be read' without it.\n" +
      "[mcp] It is generated from psu-catalog-pipeline — check that its data is present.",
  );
  process.exit(1);
}
